def find_path(graph, start, goal):
    # Initialize a dictionary to hold the path from start to each node
    # If it's not a direct connection, it will be None
    path = {start: None}
    # Initialize a dictionary to hold the previous node in the path
    previous = {}
    # Initialize the stack for the BFS
    stack = [start]

    # Perform a breadth-first search
    while stack:
        current = stack.pop(0)
        if current == goal:
            # Reconstruct the path
            path_list = []
            while current is not None:
                path_list.append(current)
                current = previous.get(current, None)
            return path_list[::-1]  # Reverse the list to get from start to goal
        for neighbor in graph.get(current, []):
            if neighbor not in previous:
                previous[neighbor] = current
                stack.append(neighbor)

    # If we reach this point, goal is unreachable
    return None
