import heapq

def heuristic(node, goal):
    # Manhattan distance as a simple heuristic function
    return abs(node[0] - goal[0]) + abs(node[1] - goal[1])

def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    open_list = []
    closed_list = set()
    heapq.heappush(open_list, (0 + heuristic(start, goal), 0, start))

    came_from = {}
    g_scores = {node: float('infinity') for node in graph}
    g_scores[start] = 0
    f_scores = {node: 0 + heuristic(node, goal) for node in graph}
    f_scores[start] = 0

    while open_list:
        _, g_score, current = heapq.heappop(open_list)

        if current == goal:
            return reconstruct_path(came_from, current)

        closed_list.add(current)
        for neighbor in graph[current]:
            if neighbor in closed_list:
                continue

            tentative_g_score = g_scores[current] + 1  # Assuming all edges have equal cost

            if neighbor not in g_scores or tentative_g_score < g_scores[neighbor]:
                came_from[neighbor] = current
                g_scores[neighbor] = tentative_g_score
                f_scores[neighbor] = tentative_g_score + heuristic(neighbor, goal)
                if neighbor not in closed_list:
                    heapq.heappush(open_list, (f_scores[neighbor], g_scores[neighbor], neighbor))

    return None

def reconstruct_path(came_from, current):
    path = [current]
    while current in came_from:
        current = came_from[current]
        path.append(current)
    return path[::-1]

